/**
 * Server-side access to the Adhkar data (~210 KB). Only server components / route handlers import this;
 * client components get the single category they render as props.
 * Generated by scripts/build-adhkar-data.py - see README.
 */
import { normalizeArabic, skeletonArabic } from "@/lib/quran/arabic";
import raw from "./data/adhkar.json";
import type { AdhkarCategory, AdhkarGroup, HubGroup } from "./types";

const data = raw as unknown as { groups: AdhkarGroup[]; categories: AdhkarCategory[] };
const byId = new Map(data.categories.map((c) => [c.id, c]));

export const categoryIds: number[] = data.categories.map((c) => c.id);

export function getCategory(id: number): AdhkarCategory | undefined {
  return byId.get(id);
}

/** Groups in display order, each with its categories (titles + item counts only). */
export function getHub(): HubGroup[] {
  return data.groups.map((g) => ({
    id: g.id,
    ar: g.ar,
    en: g.en,
    categories: g.categories.map((id) => {
      const c = byId.get(id)!;
      return { id: c.id, ar: c.ar, en: c.en, targets: c.items.map((it) => ({ id: it.id, target: it.count ?? 1 })) };
    }),
  }));
}

/** Previous / next category in the order shown on the hub (groups flattened). */
export function getNeighbours(id: number): { prev: number | null; next: number | null } {
  const order = data.groups.flatMap((g) => g.categories);
  const i = order.indexOf(id);
  return { prev: i > 0 ? order[i - 1] : null, next: i >= 0 && i < order.length - 1 ? order[i + 1] : null };
}

export function getGroupOf(id: number): AdhkarGroup | undefined {
  return data.groups.find((g) => g.categories.includes(id));
}

export interface AdhkarHit {
  category: number;
  item: number;
  text: string;
  note: string;
}

interface Entry extends AdhkarHit {
  norm: string;
  skeleton: string;
  title: string;
}
let index: Entry[] | null = null;
function getIndex(): Entry[] {
  if (!index) {
    index = [];
    for (const c of data.categories) {
      for (const it of c.items) {
        index.push({
          category: c.id,
          item: it.id,
          text: it.text,
          note: it.note.text,
          norm: normalizeArabic(`${it.title ?? ""} ${it.text}`),
          skeleton: skeletonArabic(`${it.title ?? ""} ${it.text}`),
          title: normalizeArabic(c.ar),
        });
      }
    }
  }
  return index;
}

/** Full-text search over the dhikr texts and category titles (Arabic, diacritics ignored). */
export function searchAdhkar(query: string, limit = 25): { hits: AdhkarHit[]; truncated: boolean } {
  const nq = normalizeArabic(query.trim().slice(0, 80));
  if (nq.length < 2) return { hits: [], truncated: false };
  const sq = skeletonArabic(query.trim().slice(0, 80));
  const found: Entry[] = [];
  const seen = new Set<string>();
  const add = (match: (e: Entry) => boolean) => {
    for (const e of getIndex()) {
      if (found.length > limit) return;
      const key = `${e.category}:${e.item}`;
      if (seen.has(key) || !match(e)) continue;
      seen.add(key);
      found.push(e);
    }
  };
  add((e) => e.title.includes(nq));
  add((e) => e.norm.includes(nq));
  if (found.length <= limit && sq.length >= 2) add((e) => e.skeleton.includes(sq));
  return {
    hits: found.slice(0, limit).map(({ category, item, text, note }) => ({ category, item, text, note })),
    truncated: found.length > limit,
  };
}
